/*
 * ko_select - kernel detection and module image selection.
 *
 * This is the only part of the exploit that is version aware. It reads the
 * running kernel's uname() release string, derives the GKI KMI from it
 * (android<release>-<major>.<minor>) and picks the matching embedded module
 * image. Nothing here touches the exploitation itself: it produces a pointer
 * range that exp.c then patches into the vendor library like any other blob.
 *
 * The source of truth for the KMI list is kmi.def, which is (re)generated by
 * the build from the .ko files actually present in jni/ko/. That keeps this
 * file and the build in sync: adding a module means dropping a .ko in place
 * and letting the build regenerate the table.
 */
#ifndef KO_SELECT_H
#define KO_SELECT_H

#include <stddef.h>

struct ko_image {
    int         android_release;   /* GKI release, e.g. 13 for android13-5.15 */
    int         kver_major;        /* 5 */
    int         kver_minor;        /* 15 */
    const char *start;             /* first byte of the embedded .ko */
    const char *end;               /* one past the last byte */
};

/* Result of reading the running kernel. */
struct kernel_id {
    int  android_release;   /* parsed from the "androidNN" tag, 0 if absent */
    int  kver_major;
    int  kver_minor;
    char release[256];      /* raw uname().release, for logging */
};

/*
 * Fill in `id` from the running kernel. Returns 0 on success, -1 if the
 * release string cannot be parsed (non-GKI or unreadable uname).
 */
int kernel_id_read(struct kernel_id *id);

/*
 * Pick the module image for `id`.
 *
 * Matching rules, in order:
 *   1. kernel major.minor must be equal  - a 5.15 module can never load on
 *      a 6.1 kernel, so this is a hard filter.
 *   2. exact android release match wins.
 *   3. otherwise the first image with the same kernel version is used as a
 *      fallback, on the assumption that a GKI point release keeps the KMI
 *      stable even if the android version number moved.
 *
 * Returns NULL when no image shares the kernel major.minor, i.e. the device
 * is unsupported.
 */
const struct ko_image *ko_image_select(const struct kernel_id *id);

/* Number of images compiled in, and direct access for diagnostics. */
size_t ko_image_count(void);
const struct ko_image *ko_image_at(size_t index);

/*
 * One-line human readable description of a selection, e.g.
 * "android13-5.15". Writes into `buf`.
 */
void ko_image_describe(const struct ko_image *img, char *buf, size_t buflen);

/*
 * Print every compiled-in image. Used by the unsupported-kernel path and by
 * diagnostics, so a pasted log shows what the build actually supports.
 */
void ko_image_list(void);

#endif /* KO_SELECT_H */
